// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;
    address owner;

    function setUp() public {
        c = new MyContract();
        owner = address(this);
    }

    function testFuzz_property(uint96 amount) public {
        uint amt = bound(uint256(amount), 1, type(uint96).max);
        Reverter r = new Reverter();
        vm.deal(address(c), amt);
        uint before = address(c).balance;
        bool ok;
        try c.sendTo(address(r), amt) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(!ok || address(c).balance == before - amt);
    }
}

contract Reverter {
    fallback() external payable {
        revert();
    }
}
